function F(r){ return (r && r.fields && typeof r.fields==='object') ? r.fields : (r||{}); }
const trig = $('When Executed by Another Workflow').first().json;
const cfg  = F($('Airtable · Get Config').first().json);
const branches = $('Airtable · Get All Branches').all().map(i=>F(i.json)).filter(b=>b.sucursal_id);

function norm(s){ return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim(); }
function coberturaList(b){ return norm(b.cobertura_colonias).split(',').map(x=>x.trim()).filter(Boolean); }

// ciudad_lead: la manda el MAIN, o si no la leemos del CRM.
// El MAIN corre este sub EN PARALELO con el Hydrator, asi que no puede
// pasarnosla; por eso el sub se la busca solo. Sin esto el geo redetecta
// desde cero en cada turno y el lead "pierde" su ciudad entre mensajes.
let ciudadCRM = '', coloniaCRM = '';
try {
  const r = $('Airtable · Get Lead Ciudad').all().map(i=>i.json).filter(x=>x && x.id)[0];
  if (r) { const f = F(r); ciudadCRM = f.ciudad || ''; coloniaCRM = f.colonia || ''; }
} catch(e) {}

const ciudadLead = norm(trig.ciudad_lead || ciudadCRM || coloniaCRM);
const msg = norm(trig.message_text);

let detectedCity=null, confianza='baja', via='ninguna';
if (ciudadLead){ const h=branches.find(b=>norm(b.ciudad)===ciudadLead); if(h){detectedCity=norm(h.ciudad);confianza='alta';via='ciudad_lead';} }
if (!detectedCity && ciudadLead){ const h=branches.find(b=>coberturaList(b).includes(ciudadLead)); if(h){detectedCity=norm(h.ciudad);confianza='alta';via='cobertura_lead';} }
if (!detectedCity && msg){ const h=branches.find(b=>b.ciudad && msg.includes(norm(b.ciudad))); if(h){detectedCity=norm(h.ciudad);confianza='media';via='texto_ciudad';} }
if (!detectedCity && msg){ const h=branches.find(b=>coberturaList(b).some(col=>col && msg.includes(col))); if(h){detectedCity=norm(h.ciudad);confianza='media';via='texto_colonia';} }

function pack(b){ return { sucursal_id:b.sucursal_id||'', sucursal_nombre:b.nombre||'', ciudad:b.ciudad||'', direccion:b.direccion||'', google_maps:b.google_maps||'', horario:b.horario||'', whatsapp:b.whatsapp_publico||'', telefono:b.telefono||'', gerente_nombre:b.gerente_nombre||'' }; }
const todas = branches.map(pack);
let sucursales_ciudad = detectedCity ? branches.filter(b=>norm(b.ciudad)===detectedCity).map(pack) : [];
const ciudades_cobertura = [...new Set(branches.map(b=>b.ciudad).filter(Boolean))];

// ¿Vale la pena preguntar al LLM? Solo si el código NO detectó ciudad y el mensaje trae
// tokens que no son puro saludo/relleno (posible nombre de lugar). Evita LLM en "Hola".
const FILLER = new Set(['hola','ola','holi','buenas','buenos','dias','tardes','noches','buen','dia','que','tal','hey','hello','saludos','onda','quiubo','info','informacion','informes','precio','precios','costo','cuesta','moto','motos','motocicleta','credito','financiamiento','contado','si','sii','no','ok','oki','va','vale','sale','claro','gracias','porfa','favor','quiero','una','un','el','la','los','las','de','en','me','interesa','ver','saber','pulsar','boxer','dominar','avenger','platina','ns200','ns160','ns125','n160','n250','rs200','ns400z']);
const tokens = msg.split(/[^a-z0-9]+/).filter(Boolean);
const nonFiller = tokens.filter(t=>!FILLER.has(t) && t.length>=3);
const needs_llm = !detectedCity && nonFiller.length>0;

return [{ json: {
  _cfg: cfg, _todas: todas, _sucursales_ciudad: sucursales_ciudad, _ciudades_cobertura: ciudades_cobertura,
  detectedCity, confianza, via, needs_llm, msg_raw: trig.message_text || '',
  _ciudad_crm: ciudadCRM, _colonia_crm: coloniaCRM
}}];

const g = $('Code · Geo Match (capa código)').first().json;
const cfg = g._cfg || {};
const todas = g._todas || [];
let sucursales_ciudad = g._sucursales_ciudad || [];
let detectedCity = g.detectedCity || null;
let confianza = g.confianza || 'baja';
let via = g.via || 'ninguna';
let ciudad_desconocida, fuera_cobertura;

// ¿Corrió el LLM?
let llm=null;
try { llm = $('LLM · Resolver Ciudad').first().json.output || $('LLM · Resolver Ciudad').first().json; } catch(e) {}

function norm(s){ return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim(); }

if (llm && llm.estado) {
  if (llm.estado === 'cubierta' && llm.ciudad_detectada) {
    const c = norm(llm.ciudad_detectada);
    const hit = todas.filter(b => norm(b.ciudad) === c);
    if (hit.length) { detectedCity = c; sucursales_ciudad = hit; confianza='media'; via='llm_cubierta'; }
  } else if (llm.estado === 'fuera_cobertura') {
    detectedCity = llm.ciudad_detectada ? norm(llm.ciudad_detectada) : null;
    via='llm_fuera'; confianza='media';
  } else {
    via='llm_desconocida';
  }
}

// Estados finales
if (sucursales_ciudad.length > 0) { ciudad_desconocida=false; fuera_cobertura=false; }
else if (llm && llm.estado==='fuera_cobertura') { ciudad_desconocida=false; fuera_cobertura=true; }
else { ciudad_desconocida=true; fuera_cobertura=false; }

const lista = (sucursales_ciudad.length>0) ? sucursales_ciudad : todas;
const multiple = lista.length>1;
const tipo_cita_sugerido = fuera_cobertura ? 'Videollamada' : 'Visita a sucursal';

return [{ json: {
  negocio_nombre: cfg.nombre_negocio || 'Rivas Motors',
  agente_nombre: cfg.agente_nombre || 'Asesor de venta Bajaj',
  horario_humano: cfg.horario_humano || '',
  horario_agente: cfg.horario_agente || '24/7',
  metodos_pago: cfg.metodos_pago || '',
  politica_envio: cfg.politica_envio || '',
  detected_city: detectedCity || null,
  ciudad_desconocida: ciudad_desconocida,
  fuera_cobertura: fuera_cobertura,
  geo_confianza: confianza,
  geo_via: via,
  multiple_sucursales: multiple,
  num_sucursales: lista.length,
  sucursales_ciudad: lista,
  tipo_cita_sugerido: tipo_cita_sugerido
}}];
